) VALUES
(
  'requests-per-second-calculator',
  'Requests Per Second (RPS) Calculator',
  'Calculate average requests per second from a measured request count and elapsed time, with equivalent per-minute, per-hour and request-interval results.',
  'Developer Tools', 1,
  json('["server-capacity-calculator","storage-capacity-calculator","website-carbon-footprint-calculator"]'),
  'Requests Per Second Calculator – RPS & Throughput',
  'Calculate requests per second from total completed requests and elapsed time. Convert the result to requests per minute, per hour and average interval.',
  json('["requests per second calculator","rps calculator","request rate calculator","api throughput calculator","requests per minute calculator","load test throughput","http requests per second"]'),
  '<h2>What requests per second measures</h2><p>Requests per second is an observed throughput rate: the number of completed requests divided by the elapsed measurement period. It is useful for summarising an API test, access-log interval or known traffic window. It does not by itself prove that responses were successful or fast.</p><h2>Use one consistent measurement window</h2><p>Count requests and duration over the same interval. If a load test completed 6,000 requests in 60 seconds, average throughput was 100 RPS. If the count includes failed requests, the result is attempted throughput rather than successful throughput; separate the success and error counts when that distinction matters.</p><h2>Worked RPS example</h2><p>For 18,000 completed requests over three minutes, first convert three minutes to 180 seconds. RPS is 18,000 ÷ 180 = 100. The equivalent rates are 6,000 requests per minute and 360,000 requests per hour. At a perfectly even rate, the average interval is 10 milliseconds between request starts.</p><h2>RPS is not concurrent users</h2><p>Request rate describes how often work arrives or completes. Concurrency also depends on request or iteration duration. At 100 RPS and an average one-second operation, roughly 100 operations may be in progress; at the same RPS and 100 milliseconds, roughly 10 may be in progress. Real systems need percentile latency and load-test evidence rather than an average-only assumption.</p><h2>Validate throughput with errors and latency</h2><p>Grafana k6 reports request rate, failed-request rate and request duration as separate metrics. Review them together: a higher RPS is not useful if errors rise or response-time percentiles exceed the service objective. The calculator performs only the rate conversion and does not run traffic against a website.</p><p>Reference: <a href="https://grafana.com/docs/k6/latest/using-k6/metrics/" target="_blank" rel="noopener noreferrer">Grafana k6 metrics documentation</a>.</p>',
  'Use request counts taken from one clearly defined interval. This calculator converts measured traffic into an average rate; it does not generate requests, test an external website or determine whether the measured responses met an error or latency objective.',
  json('{"title":"Throughput is one part of a load-test result","badge":"Measured request-rate formula","stat":"RPS = requests ÷ seconds","description":"Review request rate beside failed-request rate and latency percentiles. A rate alone cannot show whether the system remained reliable or responsive.","source":"Grafana k6 metrics and arrival-rate documentation","lastUpdated":"October 2026"}'),
  json('[{"step":1,"title":"Choose one measurement window","description":"Use a request count and elapsed duration that cover exactly the same test or log interval.","icon":"clock"},{"step":2,"title":"Enter completed requests","description":"Use successful requests when measuring useful throughput, or label the result as attempted throughput if failures are included.","icon":"calculator"},{"step":3,"title":"Enter duration and unit","description":"Provide seconds, minutes or hours; the calculator converts the interval to seconds.","icon":"calculator"},{"step":4,"title":"Interpret the rate with test metrics","description":"Compare RPS with error rate and percentile latency before deciding that a target system handled the load.","icon":"result"}]'),
  json('{"title":"Requests per second formula","formula":"RPS = Total requests ÷ Elapsed seconds; Average interval (ms) = 1,000 ÷ RPS","explanation":"Duration is converted to seconds before division. Requests per minute equals RPS × 60 and requests per hour equals RPS × 3,600. These are average equivalent rates; bursty traffic can have much higher short-window peaks.","example":{"input":"6,000 completed requests in 60 seconds","output":"100 RPS; 6,000 requests/minute; 360,000 requests/hour; 10 ms average interval"},"useCases":["Summarising API load-test throughput","Converting access-log counts to RPS","Comparing equal-duration benchmark runs","Estimating an average request interval"]}'),
  json('[{"question":"How do I calculate requests per second?","answer":"Divide the total request count by the elapsed duration in seconds. Convert minutes to seconds by multiplying by 60 and hours by multiplying by 3,600 before calculating the rate."},{"question":"Should failed requests be included in RPS?","answer":"That depends on the metric being reported. All attempted requests describe offered traffic, while successful requests describe useful throughput. Report the failure rate separately so a high request rate does not hide errors."},{"question":"Is RPS the same as concurrent users?","answer":"No. RPS is a rate, while concurrency is work in progress at the same time. Concurrency depends on request or iteration duration as well as rate, so the same RPS can require different concurrency levels."},{"question":"Why can short-window RPS differ from the full-test average?","answer":"Traffic can arrive in bursts. Dividing the full request count by total duration smooths those peaks, while a one-second or sub-second window can expose a higher instantaneous rate."},{"question":"Does a high RPS prove the server performed well?","answer":"No. Check failed-request rate and latency percentiles at the same load. Throughput can remain high while responses slow down or errors increase, especially near saturation."},{"question":"Does this calculator send requests to a website?","answer":"No. It only converts numbers entered in the browser. Use an authorised load-testing tool and test only systems you own or have explicit permission to assess."}]'),
  'requests-per-second-calculator', 'published', 122
),
(
  'storage-capacity-calculator',
  'Storage Capacity Calculator',
  'Estimate logical data size, storage consumed by multiple copies and provisioned capacity after a reserve using file or record count and average item size.',
  'Developer Tools', 1,
  json('["server-capacity-calculator","requests-per-second-calculator","website-carbon-footprint-calculator"]'),
  'Storage Capacity Calculator – Data, Copies & Reserve',
  'Estimate required storage from item count and average size. Include replication or backup copies and a capacity reserve, with results in binary storage units.',
  json('["storage capacity calculator","data storage calculator","disk capacity calculator","file storage calculator","database size estimator","replication storage calculator","storage planning calculator"]'),
  '<h2>What this storage estimate includes</h2><p>The calculator multiplies the number of files or records by their average size to find logical data volume. It then multiplies by the number of stored copies and adds the selected reserve. This produces a transparent planning figure without assuming a particular cloud provider, filesystem or database engine.</p><h2>Binary storage units used</h2><p>Inputs use KiB, MiB, GiB and TiB, where each step equals 1,024 of the previous unit. That avoids mixing binary capacity with decimal vendor units such as KB, MB, GB and TB, where each step equals 1,000. Confirm which convention appears on a storage product or invoice before comparing its advertised capacity.</p><h2>Worked storage example</h2><p>For 100,000 objects averaging 2.5 MiB, logical data is 250,000 MiB, or about 244.14 GiB. With three stored copies, the replicated amount is about 732.42 GiB. Adding a 20% reserve gives a provisioned target of about 878.91 GiB.</p><h2>What stored copies means</h2><p>A value of one represents one stored instance of every item. Use two for two complete copies or three for three complete copies. Replication, erasure coding, snapshots and incremental backups do not always consume a simple whole-number multiple; use an effective copy factor only when it accurately represents the chosen design.</p><h2>What the reserve should cover</h2><p>The reserve can represent expected near-term growth and operational headroom. It does not automatically calculate filesystem metadata, database indexes, object versioning, deleted-object retention, temporary files, compression or deduplication. Measure or estimate those separately and include them in the average item size, copy factor or reserve.</p><h2>Capacity is not a durability design</h2><p>Enough bytes do not guarantee recoverability. AWS storage guidance treats capacity, data protection, replication, availability and recovery requirements as separate design considerations. Define backup and restore objectives before purchasing capacity.</p><p>Reference: <a href="https://docs.aws.amazon.com/decision-guides/latest/storage-on-aws-how-to-choose/storage-on-aws-how-to-choose.html" target="_blank" rel="noopener noreferrer">AWS storage decision guide</a>.</p>',
  'Estimate storage from measurable data volume rather than choosing a disk size by guesswork. The result covers logical bytes, complete stored copies and a selected reserve; it does not claim that capacity alone provides backup, durability or performance.',
  json('{"title":"Separate logical data from provisioned storage","badge":"Binary-capacity planning","stat":"Items × average size × copies","description":"The final reserve is planning headroom. Account separately for indexes, metadata, snapshots, versioning, compression, deduplication and recovery design when they apply.","source":"Binary unit arithmetic and AWS storage planning guidance","lastUpdated":"October 2026"}'),
  json('[{"step":1,"title":"Count the stored items","description":"Enter the number of files, objects, database records or other equal-sized planning units.","icon":"calculator"},{"step":2,"title":"Measure a representative average size","description":"Use KiB, MiB, GiB or TiB and sample real data when item sizes vary widely.","icon":"calculator"},{"step":3,"title":"Represent complete stored copies","description":"Enter one for a single copy or a whole-number multiple only when the design stores complete copies.","icon":"calculator"},{"step":4,"title":"Add explicit capacity reserve","description":"Choose headroom for measured growth and known overhead, then review exclusions before provisioning.","icon":"result"}]'),
  json('{"title":"Storage capacity planning formula","formula":"Logical bytes = Item count × Average item bytes; Replicated bytes = Logical bytes × Copies; Provisioned bytes = Replicated bytes × (1 + Reserve % ÷ 100)","explanation":"The calculator uses binary units: 1 KiB = 1,024 bytes, 1 MiB = 1,024 KiB, 1 GiB = 1,024 MiB and 1 TiB = 1,024 GiB. Copy count models complete copies only. Reserve is an explicit percentage added after copies.","example":{"input":"100,000 items × 2.5 MiB, 3 copies, 20% reserve","output":"244.14 GiB logical; 732.42 GiB after copies; 878.91 GiB to provision"},"useCases":["Object-storage capacity planning","Database-record volume estimates","Media archive sizing","Replication and backup-copy estimates","Near-term growth headroom"]}'),
  json('[{"question":"Which inputs are required for the storage estimate?","answer":"Enter an item count, representative average size, number of complete stored copies and reserve percentage. Every result follows directly from those four planning assumptions."},{"question":"What is the difference between GiB and GB?","answer":"GiB is binary: 1 GiB equals 1,024 cubed bytes. GB is decimal: 1 GB equals 1,000 cubed bytes. This calculator uses binary KiB, MiB, GiB and TiB consistently."},{"question":"Should replication be entered as stored copies?","answer":"Yes when the system stores complete copies. More complex erasure coding or incremental backup designs may not equal a whole-number copy factor, so use measured effective overhead instead of guessing."},{"question":"Are database indexes and filesystem metadata included?","answer":"Not automatically. Include them in a measured average item size or reserve when known. Index size, metadata, temporary space, version history and deleted-object retention vary by system."},{"question":"How much reserve should I choose?","answer":"Use a percentage supported by expected growth, procurement lead time and operational needs. The default is only a starting input, not a universal recommendation; replace it with your measured forecast."},{"question":"Does provisioned capacity replace a backup plan?","answer":"No. Capacity, durability, availability, backup retention and restore testing are separate concerns. Multiple copies can still be lost through deletion, corruption or shared failure domains without an appropriate recovery design."}]'),
  'storage-capacity-calculator', 'published', 123
),
(
  'server-capacity-calculator',
  'Server Capacity Calculator',
  'Estimate application-server count from expected peak requests per second, measured maximum throughput per server and a target utilization percentage.',
  'Developer Tools', 1,
  json('["requests-per-second-calculator","storage-capacity-calculator","website-carbon-footprint-calculator"]'),
  'Server Capacity Calculator – Estimate Servers from RPS',
  'Estimate application server count from peak RPS, measured maximum RPS per server and target utilization. See planned throughput and remaining headroom.',
  json('["server capacity calculator","server sizing calculator","servers required calculator","rps capacity planning","web server capacity","horizontal scaling calculator","api server sizing"]'),
  '<h2>Why server capacity needs a benchmark</h2><p>CPU count and memory alone cannot determine how many requests an application server will handle. Capacity depends on application code, database calls, cache hit rate, payload size, encryption, network, runtime settings and the required latency and error thresholds. This calculator therefore asks for measured maximum RPS per server from a representative benchmark.</p><h2>Define measured maximum RPS carefully</h2><p>Use a test with production-like code, data, dependencies and request mix. The benchmark limit should be the highest per-server throughput observed before the chosen latency or error objective is breached, not merely the highest number printed by a load generator.</p><h2>Worked server-sizing example</h2><p>Suppose expected peak traffic is 1,000 RPS and one application server reached 250 RPS at the benchmark limit. With a 70% utilization target, planned capacity per server is 175 RPS. Required servers = ceiling of 1,000 ÷ 175 = 6. Six servers provide 1,050 RPS of planned capacity, leaving 50 RPS above the entered peak.</p><h2>Why target utilization is included</h2><p>Running every server at its benchmark maximum leaves no room for variation. The utilization input deliberately reduces planned per-server capacity. Choose it from operational evidence, autoscaling delay and workload variability rather than treating the default as a standard.</p><h2>What the result excludes</h2><p>The result is the workload count needed for the entered throughput assumptions. It does not add nodes for zone failure, rolling deployment, maintenance, warm-up, uneven load balancing or dependency bottlenecks. Add failover capacity according to the availability architecture and verify that databases, caches, queues and external services can support the same peak.</p><h2>Validate after rounding to whole servers</h2><p>Server count is rounded upward because a fraction of a server cannot normally carry an independent application instance. Run a staged load test against the proposed fleet and watch request rate, failed requests, latency percentiles and saturation. Grafana k6 documents these as separate metrics and notes that required virtual users depend on iteration duration.</p><p>References: <a href="https://grafana.com/docs/k6/latest/using-k6/metrics/" target="_blank" rel="noopener noreferrer">k6 metrics</a> and <a href="https://grafana.com/docs/k6/latest/using-k6/scenarios/concepts/arrival-rate-vu-allocation/" target="_blank" rel="noopener noreferrer">arrival-rate allocation</a>.</p>',
  'A meaningful server estimate starts with measured throughput from your application, not a generic CPU-to-RPS assumption. Enter a per-server benchmark captured at acceptable latency and errors, then reserve utilization headroom for normal variation.',
  json('{"title":"Benchmark first, then calculate fleet size","badge":"Measured-throughput model","stat":"ceil(Peak RPS ÷ planned RPS/server)","description":"The result sizes application instances for throughput. Availability spares and downstream database, cache, queue or network capacity require separate validation.","source":"Grafana k6 request-rate, latency and arrival-rate guidance","lastUpdated":"October 2026"}'),
  json('[{"step":1,"title":"Measure one-server throughput","description":"Benchmark a production-like instance and record the maximum RPS that still meets the chosen latency and error objectives.","icon":"calculator"},{"step":2,"title":"Estimate peak demand","description":"Use an observed or forecast peak RPS for the same request mix rather than a daily average.","icon":"calculator"},{"step":3,"title":"Set an evidence-based utilization target","description":"Reserve operating headroom for traffic variation, autoscaling delay and performance drift.","icon":"calculator"},{"step":4,"title":"Add resilience and validate the fleet","description":"Treat the result as workload capacity, add required failover instances separately, and load test the proposed architecture.","icon":"result"}]'),
  json('{"title":"Server count from measured RPS capacity","formula":"Planned RPS/server = Measured max RPS/server × Target utilization %; Servers = ceil(Peak RPS ÷ Planned RPS/server)","explanation":"Target utilization converts the measured benchmark maximum into a lower planned operating capacity. The final count is rounded upward. Planned fleet capacity equals server count multiplied by planned RPS per server; this does not include separate failover requirements.","example":{"input":"Peak 1,000 RPS; measured maximum 250 RPS/server; target utilization 70%","output":"175 planned RPS/server; ceil(1,000 ÷ 175) = 6 servers; 1,050 RPS planned fleet capacity"},"useCases":["API horizontal-scaling estimates","Web application capacity planning","Pre-autoscaling baseline calculation","Reviewing benchmark headroom","Comparing instance types with the same workload"]}'),
  json('[{"question":"What should I enter as maximum RPS per server?","answer":"Use the highest measured throughput from one production-like server that still meets your accepted latency and error thresholds. Do not use a hardware-vendor claim or a benchmark for a different workload."},{"question":"Why is target utilization required?","answer":"It keeps planned operation below the measured benchmark maximum. This creates throughput headroom, but the chosen percentage should reflect workload variation, autoscaling delay and operational evidence."},{"question":"Why is the server count rounded up?","answer":"The formula can produce a fractional requirement, but application instances are normally provisioned as whole units. Rounding down would leave planned capacity below the entered peak."},{"question":"Does the result include high-availability or failover servers?","answer":"No. It estimates instances needed for the specified workload. Add capacity for zone loss, maintenance, deployment and other failure scenarios according to the system availability design."},{"question":"Can CPU cores and RAM alone predict server RPS?","answer":"No. Throughput also depends on application code, request mix, database and cache behaviour, payloads, network, runtime settings and latency objectives. A representative benchmark is required."},{"question":"Should I use average traffic or peak traffic?","answer":"Use the peak interval the system must handle for this calculation. A daily average can hide bursts and may undersize the fleet. Keep the peak window and request mix consistent with the per-server benchmark."},{"question":"What should be checked after calculating server count?","answer":"Load test the proposed fleet and review request rate, failed requests, latency percentiles, CPU, memory, queues and downstream services. The arithmetic cannot expose a database or dependency bottleneck."}]'),
  'server-capacity-calculator', 'published', 124
);
